Section ToRefill.
  Variables (ra sp gp tp t0 t1 t2 s1 a2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (mc : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (CA c : Z).
  Let P := CA + PCLASS_SIZE * c.
  Hypothesis MI : mem_inv asegs m.
  Hypothesis HC : 1 <= c < 32.
  Hypothesis CAR : akobj CA 2592 /\ CA + 2592 <= aceil /\ CA mod 16 = 0.
  Hypothesis PC1 : rw_cells asegs m P [C4 (wz 0); C4 mc].

  Let CAE : 4096 <= CA /\ CA + 2592 <= aceil. Proof. exact (akobj_env _ _ (proj1 CAR) ltac:(clear; lia)). Qed.   (* [comment removed for export] *)
